const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];const main=$('#main'),modalRoot=$('#modal-root');let ME=null,DASH=null,activeTab='dashboard',chart=null;
async function api(url,opts={}){if(opts.body&&typeof opts.body!=='string'){opts.headers={'Content-Type':'application/json',...(opts.headers||{})};opts.body=JSON.stringify(opts.body);}const r=await fetch(url,opts);const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'خطا');return d;}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;$('#toast-root').appendChild(t);setTimeout(()=>t.remove(),2600);}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function modal(html){modalRoot.innerHTML=`<div class="modal-back"><div class="modal"><button class="btn close" onclick="closeModal()">بستن ✕</button>${html}</div></div>`;}
function closeModal(){modalRoot.innerHTML='';if(chart){chart.destroy();chart=null;}}
function printPdf(url){window.open(url,'_blank');}
async function init(){ME=await api('/api/me');if(!ME||!ME.group){location.href='/';return;}$('#admin-tab').classList.toggle('hidden',ME.role!=='admin');$('#btn-logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.href='/';};$('#btn-schedule').onclick=scheduleModal;$('#btn-queue').onclick=queueModal;$('#global-search').addEventListener('input',search);$('#tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;activeTab=b.dataset.tab;$$('#tabs button').forEach(x=>x.classList.toggle('active',x===b));render();};render();setInterval(()=>{if(activeTab==='dashboard')loadDashboard(false);},60000);}
async function render(){if(activeTab==='dashboard')return loadDashboard(true);if(activeTab==='aux')return loadAux();if(activeTab==='registry')return loadRegistry();if(activeTab==='training')return loadTraining();if(activeTab==='problems')return loadProblems();if(activeTab==='admin')return loadAdmin();}
async function loadDashboard(full){DASH=await api('/api/dashboard');$('#hdr-date').textContent=`${DASH.weekday} ${DASH.date} — ${DASH.time}`;$('#hdr-shift').textContent=`${DASH.shift.label}: ${DASH.shift.members.join(' و ')}`;$('#queue-count').textContent=DASH.queue.pending||0;const alerts=DASH.alerts.map(a=>`<div class="alert ${a.severity}" data-alert="${a.id}"><span>${esc(a.message)}</span><button class="btn" onclick="ack(${a.id},'seen');event.stopPropagation()">دیدم</button><button class="btn" onclick="ack(${a.id},'acted');event.stopPropagation()">اقدام کردم</button></div>`).join('')||'<div class="muted">هشدار فعالی وجود ندارد.</div>';const safety=DASH.safety.map(s=>`<span class="safety-item ${s.status==='repair'?'repair':''}">${esc(s.tag)} — ${esc(s.status_fa)}</span>`).join('');const intervals=DASH.intervals.map(i=>`<div class="interval ${i.filled?'filled':'missing'} ${i.current?'current':''}" onclick="pickInterval(${i.index})">${i.label}${i.filled?' ✓':i.current?' ⏳':''}</div>`).join('');const process=DASH.process.map(p=>`<div class="param ${isOut(p)?'out':''}"><div class="tag">${p.tag}</div><label>${esc(p.label)} (${esc(p.unit)})</label><input class="num" type="number" step="any" data-process="${p.tag}" value="${p.value??''}" placeholder="—"><button class="btn small" onclick="chartParam('process','${p.tag}')">📈</button>${p.edited?'<span class="badge yellow">ویرایش شد</span>':''}</div>`).join('');const motors=DASH.motors.map(m=>motorTile(m)).join('');main.innerHTML=`<div class="alertbar">${alerts}</div><div class="panel"><h2>تجهیزات حیاتی ایمنی</h2><div class="safety-strip">${safety}</div></div><div class="panel"><h2>بازه‌های ثبت ۴ساعته — ${DASH.date}</h2><div class="intervals">${intervals}</div><p class="muted small">ثبت با Enter انجام می‌شود. ساعت ثبت در گزارش، ساعت شروع بازه است. بازه‌های گذشته نیز قابل پر شدن هستند.</p></div><div class="panel"><h2>پارامترهای فرآیندی</h2><div class="process-grid">${process}</div><div class="param" style="margin-top:10px"><div class="tag">TOTAL-FIT</div><label>توتال روزانه دبی (m³) — مستقل از شیفت</label><input class="num" type="number" step="any" id="daily-total" value="${DASH.daily_total?.value??''}"><button class="btn small" onclick="totalChart()">📈</button></div></div><div class="panel"><h2>موتورهای اصلی M-01 تا M-08</h2><div class="motor-grid">${motors}</div></div><div class="panel"><h2>گزارش دستی اپراتور</h2><textarea id="operator-text" rows="4" style="width:100%"></textarea><button class="btn primary" onclick="saveOperatorText()">ثبت گزارش</button></div><div class="panel"><button class="btn primary" onclick="sendDaily(false)">ساخت PDF</button> <button class="btn primary" onclick="sendDaily(true)">ارسال اطلاعات به بله/ایتا</button> <button class="btn" onclick="correctionModal()">PDF اصلاحی</button> <button class="btn" onclick="reportsModal()">آرشیو گزارش‌ها</button> <button class="btn" onclick="alertsModal()">تاریخچه هشدارها</button></div>`;$$('[data-process]').forEach(inp=>inp.addEventListener('keydown',e=>{if(e.key==='Enter')saveProcess(inp);}));$('#daily-total').addEventListener('keydown',e=>{if(e.key==='Enter')saveTotal();});const op=await api('/api/operator-report');$('#operator-text').value=op.text||'';$$('.alert').forEach(el=>el.onclick=()=>alertsModal());}
function isOut(p){const s=p.setpoint;if(!s||p.value==null)return false;return (s.warn_min!=null&&p.value<s.warn_min)||(s.warn_max!=null&&p.value>s.warn_max)||(s.crit_min!=null&&p.value<s.crit_min)||(s.crit_max!=null&&p.value>s.crit_max);}
function motorTile(m){const pct=m.service_pct,cls=pct>=90?'crit':pct>=50?'warn':'';return `<div class="motor ${m.state}" onclick="motorModal(${m.id})"><div class="head"><b class="num">${m.tag} / ${m.pump_tag}</b><span><span class="led ${m.state}"></span> ${m.state_fa}</span></div><svg viewBox="0 0 200 60"><rect x="10" y="20" width="80" height="28" rx="6" fill="#16606b"/><rect x="95" y="30" width="20" height="8" fill="#90a4ae"/><circle cx="145" cy="34" r="22" fill="#1e88e5"/><rect x="138" y="4" width="14" height="16" fill="#1e88e5"/></svg><div class="bar ${cls}"><i style="width:${pct}%"></i></div><div class="small num">${m.hours_since_service.toFixed(0)} / ${m.service_interval} h</div><div class="state-toggle" onclick="event.stopPropagation()"><button class="btn small" onclick="setMotorState(${m.id},'on')">روشن</button><button class="btn small" onclick="setMotorState(${m.id},'off')">خاموش</button><button class="btn small" onclick="setMotorState(${m.id},'service')">سرویس</button></div></div>`;}
async function saveProcess(inp){try{await api('/api/process',{method:'POST',body:{param:inp.dataset.process,value:inp.value,interval:window._interval??DASH.interval}});toast('ثبت شد');loadDashboard(false);}catch(e){toast(e.message);}}
async function saveTotal(){try{await api('/api/total',{method:'POST',body:{value:$('#daily-total').value}});toast('توتال ثبت شد');}catch(e){toast(e.message);}}
function pickInterval(i){window._interval=i;toast(`بازه ${DASH.intervals[i].label} انتخاب شد`);}
async function setMotorState(id,state){if(!confirm('تغییر وضعیت موتور ثبت شود؟'))return;try{await api(`/api/motors/${id}/state`,{method:'POST',body:{state}});loadDashboard(false);}catch(e){toast(e.message);}}
async function ack(id,kind){try{await api(`/api/alerts/${id}/ack`,{method:'POST',body:{kind}});toast(kind==='seen'?'ثبت دیدم':'ثبت اقدام');loadDashboard(false);}catch(e){toast(e.message);}}
async function saveOperatorText(){await api('/api/operator-report',{method:'POST',body:{text:$('#operator-text').value}});toast('گزارش ثبت شد');}
async function sendDaily(send){try{const r=await api('/api/reports/daily',{method:'POST',body:{send}});toast(send?'در صف ارسال قرار گرفت':'PDF ساخته شد');printPdf(r.url);}catch(e){toast(e.message);}}
async function motorModal(id){const d=await api(`/api/motors/${id}`);window._motor=d;const groups=[['جریان سه‌فاز',d.params.filter(p=>p.key.startsWith('I'))],['دماها T1-T10',d.params.filter(p=>p.key.startsWith('T'))],['یاتاقان پمپ',d.params.filter(p=>p.key.startsWith('BRG'))],['لرزش',d.params.filter(p=>p.key.startsWith('VIB'))]];const fields=groups.map(([title,ps])=>`<h3>${title}</h3><div class="field-grid">${ps.map(p=>`<div class="field"><label>${esc(p.label)} (${esc(p.unit)})</label><input type="number" step="any" data-motor-param="${p.key}" value="${p.value??''}"></div>`).join('')}</div>`).join('');modal(`<h2>${d.motor.tag} — ثبت داده موتور</h2><p class="muted">${d.date} بازه ${d.interval+1} — فقط فیلدهای تغییریافته را پر کنید.</p>${fields}<div class="toolbar"><button class="btn primary" onclick="saveMotorValues(${id})">ثبت partial</button><button class="btn" onclick="motorChartModal(${id})">چارت / مقایسه</button><button class="btn" onclick="serviceModal(${id})">صفحه سرویس</button><button class="btn" onclick="meggerModal(${id})">تست مگر</button><button class="btn" onclick="oilModal(${id})">تعویض روغن</button>${ME.role==='admin'?`<button class="btn warn" onclick="hmiModal(${id})">اصلاح شمارنده HMI</button><button class="btn" onclick="setpointsModal()">ست‌پوینت‌ها</button>`:''}</div><h3>تاریخچه وضعیت</h3>${table(d.state_history.map(x=>[x.at,x.old_state||'—',x.new_state,x.shift_label]),['زمان','قبلی','جدید','شیفت'])}<h3>سرویس‌های قبلی</h3>${table(d.services.map(x=>[x.date,x.workers,x.hmi_hours,x.pdf_path?`<button class="btn small" onclick="printPdf('/api/reports/file?path=${encodeURIComponent(x.pdf_path.split('/').pop())}')">PDF</button>`:'']),['تاریخ','انجام‌دهندگان','HMI','چاپ'])}<h3>آخرین تست مگر / تعویض روغن</h3><p class="small">مگر: ${d.megger[0]?.date||'—'} | روغن: ${d.oil[0]?.date||'—'}</p>`);$$('[data-motor-param]').forEach(inp=>inp.addEventListener('keydown',e=>{if(e.key==='Enter')saveMotorValues(id);}));}
async function saveMotorValues(id){const values={};$$('[data-motor-param]').forEach(i=>{if(i.value!=='')values[i.dataset.motorParam]=i.value;});try{await api(`/api/motors/${id}/values`,{method:'POST',body:{values}});toast('ثبت شد');closeModal();loadDashboard(false);}catch(e){toast(e.message);}}
function table(rows,headers){if(!rows.length)return '<p class="muted">موردی نیست.</p>';return `<table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c??''}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
async function serviceModal(id){const d=window._motor||await api(`/api/motors/${id}`);const brush=['U','V','W'].map(ph=>`<h3>فاز ${ph}</h3><div class="field-grid">${[1,2,3,4,5,6,7,8].map(i=>`<div class="field"><label>برس ${i}</label><input data-brush="${ph}${i}" type="number" step="any"></div>`).join('')}</div>`).join('');modal(`<h2>سرویس موتور ${d.motor.tag}</h2><label>چه کسانی سرویس کردند</label><input id="svc-workers" style="width:100%"><label>تاریخ سرویس</label><input id="svc-date" value="${DASH.date}"><label>ساعت HMI</label><input id="svc-hmi" type="number" step="any" value="${d.motor.hmi_hours}"><label>یادداشت</label><textarea id="svc-note" rows="3" style="width:100%"></textarea>${brush}<p class="warning">ثبت سرویس، شمارنده ساعت-از-آخرین-سرویس را صفر می‌کند و موتور را خاموش/آماده می‌کند.</p><button class="btn primary" onclick="saveService(${id})">ثبت سرویس و ساخت PDF</button>`);}
async function saveService(id){if(!confirm('مطمئنید؟ شمارنده سرویس ریست می‌شود.'))return;const brush={};$$('[data-brush]').forEach(i=>brush[i.dataset.brush]=i.value);try{const r=await api(`/api/motors/${id}/service`,{method:'POST',body:{workers:$('#svc-workers').value,date:$('#svc-date').value,hmi_hours:$('#svc-hmi').value,note:$('#svc-note').value,brush,confirm_lower:true}});toast('سرویس ثبت شد');printPdf(r.pdf);closeModal();loadDashboard(false);}catch(e){toast(e.message);}}
async function meggerModal(id){modal(`<h2>تست مگر</h2><div class="field-grid">${['stator_u','stator_v','stator_w','rotor_u','rotor_v','rotor_w','winding_temp','pi'].map(k=>`<div class="field"><label>${k}</label><input id="mg-${k}" type="number" step="any"></div>`).join('')}</div><label>ولتاژ تست</label><select id="mg-v"><option>500</option><option selected>1000</option><option>2500</option><option>5000</option></select><button class="btn primary" onclick="saveMegger(${id})">ثبت</button>`);}
async function saveMegger(id){const body={test_voltage:$('#mg-v').value};['stator_u','stator_v','stator_w','rotor_u','rotor_v','rotor_w','winding_temp','pi'].forEach(k=>body[k]=$(`#mg-${k}`).value);await api(`/api/motors/${id}/megger`,{method:'POST',body});toast('ثبت شد');closeModal();}
async function oilModal(id){modal(`<h2>تعویض روغن پمپ</h2><label>تاریخ</label><input id="oil-date" value="${DASH.date}"><label>ساعت کارکرد</label><input id="oil-h" type="number"><label>یادداشت</label><textarea id="oil-note"></textarea><button class="btn primary" onclick="saveOil(${id})">ثبت</button>`);}
async function saveOil(id){await api(`/api/motors/${id}/oil`,{method:'POST',body:{date:$('#oil-date').value,hmi_hours:$('#oil-h').value,note:$('#oil-note').value}});toast('ثبت شد');closeModal();}
async function hmiModal(id){modal(`<h2>اصلاح شمارنده HMI</h2><p class="muted">این کار نوار ساعت-از-آخرین-سرویس را ریست نمی‌کند.</p><label>ساعت جدید</label><input id="hmi-new" type="number" step="any"><label>دلیل اصلاح</label><input id="hmi-reason"><button class="btn warn" onclick="saveHmi(${id})">ثبت اصلاح</button>`);}
async function saveHmi(id){await api(`/api/motors/${id}/hmi`,{method:'POST',body:{hours:$('#hmi-new').value,reason:$('#hmi-reason').value}});toast('اصلاح شد');closeModal();loadDashboard(false);}
async function chartParam(scope,param,motor){const h=await api(`/api/history?scope=${scope}&param=${param}${motor?`&motor=${motor}`:''}`);modal(`<h2>چارت ${param}</h2><div class="toolbar"><select id="chart-type"><option value="line">خطی</option><option value="bar">میله‌ای</option><option value="scatter">پراکنده</option></select><button class="btn" onclick="drawChart('${scope}','${param}','${motor||''}')">رسم</button></div><p class="small">میانگین: ${h.stats.avg??'—'} | کمینه: ${h.stats.min??'—'} | بیشینه: ${h.stats.max??'—'}</p><div class="chart-box"><canvas id="chart"></canvas></div>`);window._hist=h;drawChart(scope,param,motor);}
function drawChart(scope,param,motor){const h=window._hist;const type=$('#chart-type').value;if(chart)chart.destroy();chart=new Chart($('#chart'),{type,data:{labels:h.rows.map(r=>`${r.date} ${r.interval_index+1}`),datasets:[{label:param,data:h.rows.map(r=>r.value),borderColor:'#16606b',backgroundColor:'#1e88e5'}]},options:{responsive:true,maintainAspectRatio:false}});}
async function motorChartModal(id){const d=window._motor;const opts=d.params.map(p=>`<option value="${p.key}">${p.label}</option>`).join('');modal(`<h2>چارت موتور</h2><select id="mc-param">${opts}</select><button class="btn" onclick="chartParam('motor',$('#mc-param').value,'${d.motor.tag}')">رسم</button><div class="chart-box"><canvas id="chart"></canvas></div>`);}
async function totalChart(){const y=prompt('سال شمسی',DASH.date.split('/')[0]),m=prompt('ماه',String(+DASH.date.split('/')[1]));if(!y||!m)return;const d=await api(`/api/total/monthly?year=${y}&month=${m}`);modal(`<h2>توتال ماهانه ${y}/${m}</h2><p>جمع کل: <b class="num">${d.sum}</b> m³</p><div class="chart-box"><canvas id="chart"></canvas></div>`);if(chart)chart.destroy();chart=new Chart($('#chart'),{type:'bar',data:{labels:Array.from({length:d.days},(_,i)=>i+1),datasets:[{label:'m³',data:Array.from({length:d.days},(_,i)=>d.rows.find(r=>+r.date.split('/')[2]===i+1)?.value||0),backgroundColor:'#16606b'}]},options:{responsive:true,maintainAspectRatio:false}});}
async function scheduleModal(){const roster=await api('/api/roster');const today=await api('/api/schedule');const opts=roster.map(r=>`<option value="${r.id}">${esc(r.name)} — ${esc(r.group_label)}</option>`).join('');modal(`<h2>جابجایی / مرخصی</h2><div class="toolbar"><select id="sch-type"><option value="leave">مرخصی</option><option value="swap">جابجایی</option></select><select id="sch-member">${opts}</select><select id="sch-rep"><option value="">جایگزین از روستر</option>${opts}</select><input id="sch-time" type="time"><input id="sch-note" placeholder="یادداشت"><button class="btn primary" onclick="saveSchedule()">ثبت</button></div>${table(today.map(x=>[x.time,x.type_label,x.member,x.replacement,x.note]),['ساعت','نوع','فرد','جایگزین','یادداشت'])}`);}
async function saveSchedule(){await api('/api/schedule',{method:'POST',body:{type:$('#sch-type').value,member_id:$('#sch-member').value,replacement_member_id:$('#sch-rep').value||null,time:$('#sch-time').value,note:$('#sch-note').value}});toast('ثبت شد');closeModal();}
async function queueModal(){if(ME.role!=='admin'){toast('لغو صف فقط برای ادمین است');return;}const rows=await api('/api/admin/queue');modal(`<h2>صف ارسال</h2>${table(rows.map(q=>[q.id,q.kind,q.channel_key,q.status,q.attempts,q.last_error,q.status==='pending'?`<button class="btn small danger" onclick="cancelQueue(${q.id})">لغو</button>`:'']),['شناسه','نوع','کانال','وضعیت','تلاش','خطا',''])}`);}
async function cancelQueue(id){await api(`/api/admin/queue/${id}/cancel`,{method:'POST'});toast('لغو شد');queueModal();}
async function reportsModal(){const rows=await api('/api/reports');modal(`<h2>آرشیو گزارش‌ها</h2>${table(rows.map(r=>[r.date,r.shift_label,r.kind,`<button class="btn small" onclick="printPdf('${r.id?`/api/reports/${r.id}/file`:''}')">مشاهده/چاپ</button>`]),['تاریخ','شیفت','نوع','PDF'])}`);}
async function alertsModal(){const rows=await api('/api/alerts');modal(`<h2>تاریخچه هشدارها</h2>${table(rows.map(a=>[a.created_at,a.tag,a.message,a.severity,a.seen_at||'—',a.acted_at||'—']),['زمان','تگ','پیام','شدت','دیدم','اقدام'])}`);}
async function correctionModal(){const rows=await api('/api/reports');const opts=rows.filter(r=>r.kind==='daily').map(r=>`<option value="${r.id}">${r.date} — ${r.filename}</option>`).join('');modal(`<h2>PDF اصلاحی</h2><select id="corr-from">${opts}</select><button class="btn primary" onclick="makeCorrection()">ساخت اصلاحی</button>`);}
async function makeCorrection(){const r=await api('/api/reports/daily',{method:'POST',body:{correction:true,corrected_from:$('#corr-from').value}});printPdf(r.url);closeModal();}
async function loadAux(){const rows=await api('/api/aux');main.innerHTML=`<div class="panel"><div class="toolbar"><h2>پایش تجهیزات جانبی</h2><button class="btn primary" onclick="auxPdf(false)">PDF کلی</button><button class="btn" onclick="auxPdf(true)">PDF + ارسال دستی</button></div>${table(rows.map(r=>[r.tag,r.name,`<select onchange="auxState(${r.id},this.value,'${r.status}')"><option value="on" ${r.run_state==='on'?'selected':''}>روشن</option><option value="off" ${r.run_state==='off'?'selected':''}>خاموش</option></select>`,`<select onchange="auxState(${r.id},'${r.run_state}',this.value)">${Object.entries({ready:'آماده به کار',running:'در حال کار',repair:'در حال تعمیر',service:'در حال سرویس',in_warehouse:'در انبار'}).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select>`,r.hours_since_change??'—',r.status_changed_shift||'—']),['تگ','تجهیز','روشن/خاموش','وضعیت','ساعت از تغییر','شیفت'])}</div>`;}
async function auxState(id,run,status){await api(`/api/aux/${id}/state`,{method:'POST',body:{run_state:run,status}});toast('ثبت شد');loadAux();}
async function auxPdf(send){const r=await api('/api/reports/aux',{method:'POST',body:{send}});printPdf(r.url);}
async function loadRegistry(){const cats=await api('/api/categories');main.innerHTML=`<div class="panel"><div class="toolbar"><select id="reg-cat"><option value="">همه دسته‌ها</option>${cats.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><input id="reg-q" placeholder="جستجوی زنده…"><button class="btn" onclick="regSearch()">جستجو</button>${ME.role==='admin'?'<button class="btn primary" onclick="equipmentModal()">افزودن تجهیز</button>':''}<button class="btn" onclick="registryPdf()">خروجی PDF</button></div><div id="reg-list"></div></div>`;$('#reg-cat').onchange=regSearch;$('#reg-q').oninput=regSearch;regSearch();}
async function regSearch(){const rows=await api(`/api/equipment?category=${$('#reg-cat').value}&q=${encodeURIComponent($('#reg-q').value)}`);$('#reg-list').innerHTML=table(rows.map(r=>[r.tag,r.name,r.category_name,r.status_fa,`<button class="btn small" onclick="equipmentDetail(${r.id})">پرونده</button> <button class="btn small" onclick="maintenanceModal(${r.id})">PM/تعمیرات</button> <button class="btn small" onclick="catalogModal(${r.id})">کاتالوگ</button>${ME.role==='admin'?` <button class="btn small" onclick="equipmentModal(${r.id})">ویرایش</button> <button class="btn small danger" onclick="delEquipment(${r.id})">حذف</button>`:''}`]),['تگ','نام','دسته','وضعیت','عملیات']);}
async function equipmentDetail(id){const rows=await api('/api/equipment?q=');const r=rows.find(x=>x.id===id);modal(`<h2>${esc(r.tag)} — ${esc(r.name)}</h2>${table([[ 'دسته',r.category_name],['مشخصات',r.spec],['پلاک',r.plate],['شماره قطعات',r.part_numbers],['محل',r.location],['وضعیت',r.status_fa],['یادداشت',r.notes]],['فیلد','مقدار'])}`);}
async function equipmentModal(id){const cats=await api('/api/categories');let r={};if(id){const rows=await api('/api/equipment?include_deleted=1');r=rows.find(x=>x.id===id)||{};}modal(`<h2>${id?'ویرایش':'افزودن'} تجهیز</h2><div class="field-grid"><div class="field"><label>تگ</label><input id="eq-tag" value="${esc(r.tag||'')}" ${id?'disabled':''}></div><div class="field"><label>دسته</label><select id="eq-cat">${cats.map(c=>`<option value="${c.id}" ${r.category_id==c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>نام</label><input id="eq-name" value="${esc(r.name||'')}"></div><div class="field"><label>مشخصات</label><input id="eq-spec" value="${esc(r.spec||'')}"></div><div class="field"><label>پلاک</label><input id="eq-plate" value="${esc(r.plate||'')}"></div><div class="field"><label>شماره قطعات</label><input id="eq-parts" value="${esc(r.part_numbers||'')}"></div><div class="field"><label>محل</label><input id="eq-loc" value="${esc(r.location||'')}"></div><div class="field"><label>وضعیت</label><select id="eq-status">${Object.entries({ready:'آماده به کار',running:'در حال کار',repair:'در حال تعمیر',service:'در حال سرویس',in_warehouse:'در انبار'}).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></div></div><label>یادداشت</label><textarea id="eq-notes" style="width:100%">${esc(r.notes||'')}</textarea><button class="btn primary" onclick="saveEquipment(${id||'null'})">ذخیره</button>`);}
async function saveEquipment(id){const body={tag:$('#eq-tag').value,category_id:$('#eq-cat').value,name:$('#eq-name').value,spec:$('#eq-spec').value,plate:$('#eq-plate').value,part_numbers:$('#eq-parts').value,location:$('#eq-loc').value,status:$('#eq-status').value,notes:$('#eq-notes').value};await api(id?`/api/equipment/${id}`:'/api/equipment',{method:id?'PUT':'POST',body});toast('ذخیره شد');closeModal();regSearch();}
async function delEquipment(id){if(!confirm('مطمئنید؟ رکورد حذف نرم می‌شود و داده‌های عملیاتی پاک نمی‌شوند.'))return;await api(`/api/equipment/${id}`,{method:'DELETE'});regSearch();}
async function maintenanceModal(eid){const rows=await api(`/api/maintenance?equipment_id=${eid}`);const tpls=await api('/api/pm-templates');modal(`<h2>تعمیرات / PM</h2><div class="toolbar"><select id="mt-tpl">${tpls.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><input id="mt-workers" placeholder="چه کسی/کدام شیفت"><input id="mt-date" value="${DASH?.date||''}"><input id="mt-note" placeholder="یادداشت"><button class="btn primary" onclick="saveMaintenance(${eid})">ثبت</button></div>${table(rows.map(x=>[x.date,x.shift_label,x.workers,x.note]),['تاریخ','شیفت','افراد','یادداشت'])}`);}
async function saveMaintenance(eid){await api('/api/maintenance',{method:'POST',body:{equipment_id:eid,template_id:$('#mt-tpl').value,workers:$('#mt-workers').value,date:$('#mt-date').value,note:$('#mt-note').value}});toast('ثبت شد');closeModal();}
async function catalogModal(eid){const rows=await api(`/api/equipment/${eid}/catalogs`);modal(`<h2>کاتالوگ‌ها</h2>${rows.map(c=>`<div><a target="_blank" href="/catalogs/${c.filename}">${esc(c.original_name)}</a></div>`).join('')||'<p class="muted">کاتالوگی نیست.</p>'}${ME.role==='admin'?`<input type="file" id="cat-file" accept="application/pdf"><button class="btn" onclick="uploadCatalog(${eid})">آپلود</button>`:''}`);}
async function uploadCatalog(eid){const f=$('#cat-file').files[0];if(!f)return;const fd=new FormData();fd.append('file',f);const r=await fetch(`/api/equipment/${eid}/catalogs`,{method:'POST',body:fd});const d=await r.json();if(!r.ok)toast(d.error);else{toast('آپلود شد');catalogModal(eid);}}
async function registryPdf(){const r=await api('/api/reports/registry',{method:'POST'});printPdf(r.url);}
async function loadTraining(){const rows=await api('/api/training');main.innerHTML=`<div class="panel"><h2>آموزش و دستورالعمل</h2>${ME.role==='admin'?'<button class="btn primary" onclick="trainingModal()">افزودن</button>':''}${rows.map(t=>`<div class="panel"><h3>${esc(t.title)}</h3><p>${esc(t.body).replace(/\n/g,'<br>')}</p>${ME.role==='admin'?`<button class="btn small" onclick="trainingModal(${t.id})">ویرایش</button>`:''}</div>`).join('')}</div>`;}
async function trainingModal(id){let t={title:'',body:''};if(id){const rows=await api('/api/training');t=rows.find(x=>x.id===id);}modal(`<h2>آموزش</h2><input id="tr-title" value="${esc(t.title)}" placeholder="عنوان" style="width:100%"><textarea id="tr-body" rows="8" style="width:100%">${esc(t.body)}</textarea><button class="btn primary" onclick="saveTraining(${id||'null'})">ذخیره</button>`);}
async function saveTraining(id){await api(id?`/api/training/${id}`:'/api/training',{method:id?'PUT':'POST',body:{title:$('#tr-title').value,body:$('#tr-body').value}});closeModal();loadTraining();}
async function loadProblems(){const rows=await api('/api/problems');main.innerHTML=`<div class="panel"><h2>گزارش مشکل</h2><textarea id="problem-text" rows="4" style="width:100%"></textarea><button class="btn primary" onclick="saveProblem()">ثبت گزارش مشکل</button></div><div class="panel"><h2>گزارش‌های ثبت‌شده</h2>${table(rows.map(r=>[r.at,r.shift_label,esc(r.text)]),['زمان','شیفت','متن'])}</div>${ME.role==='admin'?'<div class="panel"><h2>خطاهای فنی برنامه</h2><button class="btn" onclick="location.href=\'/api/admin/errors/export\'">خروجی برای توسعه‌دهنده</button><div id="tech-errors"></div></div>':''}`;if(ME.role==='admin'){const e=await api('/api/admin/errors');$('#tech-errors').innerHTML=table(e.map(x=>[x.at,x.message]),['زمان','خطا']);}}
async function saveProblem(){await api('/api/problems',{method:'POST',body:{text:$('#problem-text').value}});toast('ثبت شد');loadProblems();}
async function loadAdmin(){const s=await api('/api/admin/status');main.innerHTML=`<div class="panel"><h2>ادمین</h2><p>نسخه: ${s.version} | آخرین بک‌آپ: ${s.last_backup||'—'} | صف: ${JSON.stringify(s.queue)}</p><p class="small">رکوردها: ${Object.entries(s.counts).map(([k,v])=>`${k}: ${v}`).join(' | ')}</p></div><div class="panel admin-section"><h2>بک‌آپ و بازیابی</h2><button class="btn primary" onclick="backupNow()">بک‌آپ هم‌اکنون</button> <button class="btn" onclick="backupsModal()">دانلود / بازیابی</button> <button class="btn" onclick="sendBackup()">ارسال دستی به کانال بک‌آپ</button></div><div class="panel admin-section"><h2>ست‌پوینت‌ها</h2><button class="btn" onclick="setpointsModal()">مدیریت ست‌پوینت‌ها</button></div><div class="panel admin-section"><h2>افراد / PIN / شیفت فعال</h2><button class="btn" onclick="rosterModal()">روستر و PINها</button></div><div class="panel admin-section"><h2>کانال‌های ارسال</h2><button class="btn" onclick="channelsModal()">بله / ایتا</button></div><div class="panel admin-section"><h2>چک‌لیست‌های PM</h2><button class="btn" onclick="pmTemplatesModal()">قالب‌ها بر اساس دسته</button></div><div class="panel admin-section"><h2>آرشیو ماهانه</h2><button class="btn" onclick="archivesModal()">لیست / دانلود / ساخت</button></div><div class="panel admin-section"><h2>لاگ فعالیت‌ها</h2><button class="btn" onclick="location.href='/api/admin/activity/export'">خروجی CSV</button> <button class="btn" onclick="activityModal()">مشاهده</button></div><div class="panel admin-section"><h2>بروزرسانی آفلاین</h2><input type="file" id="update-file" accept=".zip"><button class="btn" onclick="uploadUpdate()">آپلود بروزرسانی</button> <button class="btn" onclick="changelogModal()">چه چیز تازه است</button></div><div class="panel admin-section"><h2>لوگو</h2><input type="file" id="logo-file" accept="image/*"><button class="btn" onclick="uploadLogo()">آپلود لوگو</button></div>`;}
async function backupNow(){const r=await api('/api/admin/backup',{method:'POST'});toast('بک‌آپ ساخته شد: '+r.name);}
async function backupsModal(){const rows=await api('/api/admin/backups');modal(`<h2>بک‌آپ‌ها</h2>${table(rows.map(b=>[b.name,b.size,`<a class="btn small" href="/api/admin/backups/${b.name}/download">دانلود</a> <button class="btn small danger" onclick="restoreBackup('${b.name}')">بازیابی</button>`]),['نام','اندازه','عملیات'])}<p class="warning">بازیابی، داده‌های فعلی را با نسخه بک‌آپ جایگزین می‌کند. قبل از آن یک بک‌آپ ایمنی گرفته می‌شود.</p>`);}
async function restoreBackup(name){if(!confirm('مطمئنید؟ سیستم به حالت این بک‌آپ برمی‌گردد.'))return;await api('/api/admin/restore',{method:'POST',body:{filename:name,confirm:true}});toast('بازیابی شد');location.reload();}
async function sendBackup(){await api('/api/admin/backup/send',{method:'POST'});toast('در صف کانال بک‌آپ قرار گرفت');}
async function setpointsModal(){const rows=await api('/api/admin/setpoints');modal(`<h2>ست‌پوینت‌ها</h2><p class="small">خالی = بدون هشدار. بازه فیزیکی فقط ورودی آشکارا اشتباه را بلاک می‌کند.</p><table class="table"><thead><tr><th>کلید</th><th>عنوان</th><th>هشدار min</th><th>هشدار max</th><th>بحرانی min</th><th>بحرانی max</th><th>فیزیکی min</th><th>فیزیکی max</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="num">${r.key}</td><td>${esc(r.label)}</td>${['warn_min','warn_max','crit_min','crit_max','phys_min','phys_max'].map(f=>`<td><input data-sp="${r.key}" data-f="${f}" value="${r[f]??''}"></td>`).join('')}<td><button class="btn small" onclick="saveSetpoint('${r.key}')">ثبت</button></td></tr>`).join('')}</tbody></table>`);}
async function saveSetpoint(key){const body={};$$(`[data-sp="${key}"]`).forEach(i=>body[i.dataset.f]=i.value);await api(`/api/admin/setpoints/${encodeURIComponent(key)}`,{method:'PUT',body});toast('ثبت شد');}
async function rosterModal(){const groups=await api('/api/admin/groups');modal(`<h2>روستر و PINها</h2>${groups.map(g=>`<div class="panel"><h3>${g.label}</h3><label>PIN جدید</label><input id="pin-${g.key}" maxlength="4"><button class="btn small" onclick="savePin('${g.key}')">تغییر PIN</button>${table(g.members.map(m=>[m.name,m.phone,m.group_key]),['نام','تلفن','گروه'])}</div>`).join('')}<h3>شیفت فعال</h3><select id="active-shift"><option>A</option><option>B</option><option>C</option></select><button class="btn" onclick="saveActiveShift()">ثبت</button>`);}
async function savePin(key){await api(`/api/admin/groups/${key}`,{method:'PUT',body:{pin:$('#pin-'+key).value}});toast('PIN تغییر کرد');}
async function saveActiveShift(){await api('/api/admin/active-shift',{method:'PUT',body:{shift:$('#active-shift').value}});toast('شیفت فعال تغییر کرد');}
async function channelsModal(){const rows=await api('/api/admin/channels');modal(`<h2>کانال‌های ارسال</h2>${rows.map(c=>`<div class="panel"><h3>${c.key==='daily'?'کانال گزارش روزانه':'کانال بک‌آپ'}</h3><select id="ch-${c.key}-provider"><option value="bale" ${c.provider==='bale'?'selected':''}>بله</option><option value="eitaa" ${c.provider==='eitaa'?'selected':''}>ایتا</option></select><input id="ch-${c.key}-chat" placeholder="chat_id" value="${esc(c.chat_id)}"><input id="ch-${c.key}-token" placeholder="توکن" type="password"><label><input type="checkbox" id="ch-${c.key}-enabled" ${c.enabled?'checked':''}> فعال</label><button class="btn" onclick="saveChannel('${c.key}')">ذخیره</button> <button class="btn" onclick="testChannel('${c.key}')">تست ارسال</button></div>`).join('')}`);}
async function saveChannel(key){await api(`/api/admin/channels/${key}`,{method:'PUT',body:{provider:$(`#ch-${key}-provider`).value,chat_id:$(`#ch-${key}-chat`).value,token:$(`#ch-${key}-token`).value,enabled:$(`#ch-${key}-enabled`).checked?1:0}});toast('ذخیره شد');}
async function testChannel(key){try{await api(`/api/admin/channels/${key}/test`,{method:'POST'});toast('تست ارسال موفق بود');}catch(e){toast(e.message);}}
async function pmTemplatesModal(){const rows=await api('/api/pm-templates');modal(`<h2>قالب چک‌لیست PM</h2>${rows.map(t=>`<div class="panel"><h3>${esc(t.name)}</h3><textarea id="pm-${t.id}" rows="4" style="width:100%">${esc(t.items_json)}</textarea><button class="btn small" onclick="savePmTemplate(${t.id})">ذخیره</button></div>`).join('')}`);}
async function savePmTemplate(id){let items=[];try{items=JSON.parse($('#pm-'+id).value);}catch(e){toast('JSON نامعتبر');return;}await api(`/api/pm-templates/${id}`,{method:'PUT',body:{items}});toast('ذخیره شد');}
async function archivesModal(){const rows=await api('/api/admin/archives');modal(`<h2>آرشیو ماهانه</h2><div class="toolbar"><input id="ar-y" placeholder="سال"><input id="ar-m" placeholder="ماه"><button class="btn" onclick="makeArchive()">ساخت دستی</button></div>${table(rows.map(a=>[`${a.year}/${a.month}`,a.created_at,`<a class="btn small" href="/api/admin/archives/${a.id}/download">دانلود</a>`]),['ماه','ساخت','دانلود'])}`);}
async function makeArchive(){await api('/api/admin/archives',{method:'POST',body:{year:$('#ar-y').value,month:$('#ar-m').value}});toast('ساخته شد');archivesModal();}
async function activityModal(){const rows=await api('/api/admin/activity');modal(`<h2>لاگ فعالیت‌ها</h2>${table(rows.map(r=>[r.at,r.shift_label,r.action,r.detail]),['زمان','شیفت','کار','جزئیات'])}`);}
async function uploadUpdate(){const f=$('#update-file').files[0];if(!f)return;const fd=new FormData();fd.append('file',f);const r=await fetch('/api/admin/update',{method:'POST',body:fd});const d=await r.json();toast(d.message||d.error);}
async function changelogModal(){const d=await api('/api/admin/changelog');modal(`<h2>چه چیز تازه است</h2><pre style="white-space:pre-wrap">${esc(d.changelog||'موردی نیست.')}</pre><button class="btn" onclick="seenChangelog()">دیدم</button>`);}
async function seenChangelog(){await api('/api/admin/changelog/seen',{method:'POST'});closeModal();}
async function uploadLogo(){const f=$('#logo-file').files[0];if(!f)return;const fd=new FormData();fd.append('file',f);await fetch('/api/admin/logo',{method:'POST',body:fd});toast('لوگو ذخیره شد');}
async function search(e){const q=e.target.value.trim();const box=$('#search-results');if(!q){box.classList.add('hidden');return;}const d=await api('/api/search?q='+encodeURIComponent(q));box.classList.remove('hidden');box.innerHTML=[...d.equipment.map(x=>`<div onclick="equipmentDetail(${x.id})">تجهیز: ${esc(x.tag)} — ${esc(x.name)}</div>`),...d.reports.map(x=>`<div onclick="printPdf('/api/reports/${x.id}/file')">گزارش: ${esc(x.date)} ${esc(x.filename)}</div>`),...d.alerts.map(x=>`<div onclick="alertsModal()">هشدار: ${esc(x.message)}</div>`)].join('')||'<div>نتیجه‌ای نیست</div>';}
init();
